export const bands={ntu:[[0,.15],[.5,.2],[.7,.25],[.8,.4],[1,.6],[1.1,.8],[1.2,1]],cash:[[0,.4],[.3,.5],[.6,.6],[.8,.7],[1,.8]],bonus:[[0,0],[.8,.05],[.9,.075],[1,.105],[1.05,.115],[1.1,.1194],[1.15,.1268],[1.2,.1341],[1.25,.1425],[1.3,.155],[1.4,.1675],[1.5,.18]]};
export const defaults={cof:35426393,non:52262125,ntu:4,done:4,wcof:.4,wnon:.6,salary:7100000,dependents:2,deduct:15500000,perDependent:6200000,insurance:0,company:null,taxBands:[[0,.05],[10000000,.1],[30000000,.2],[60000000,.3],[100000000,.35]],bands:structuredClone(bands)};
export function blank(){return {settings:structuredClone(defaults),cash:[],ntu:[]};}
export function seed(){const d=blank();d.cash=[['Hoàng Ngọc Tuân','NON',810000],['Ngô Xuân Hồ','COF',500000],['Nguyễn Thị Tuyết Phượng','COF',1000000]].map(([name,group,amount],i)=>({id:'c'+i,contract:'',name,group,amount,kind:'period',manual:1}));d.ntu=[['Đinh Thị Tuyết Minh',4821086,70711,.05],['Y Thiêl',5500000,71662,.05],['Đinh Văn Mạnh',6450000,60523,.2],['Y Bình',7050000,88812,.05],['Hoàng Thị Kép',9000000,118603,.05],['Thị Lin',11300000,148360,.05],['Lưu Thanh Tú',14750129,196362,.2],['Trần Văn Lưu',27950000,262269,.05],['Phùng Nông Ba',29104059,145059,.05]].map(([name,pos,mindue,manual],i)=>({id:'n'+i,name,contract:'',pos,mindue,manual,amount:i===7?450000:0,override:null}));return d;}
export function rate(table,n){let r=0;for(const [min,v] of table)if(n+1e-12>=min)r=v;return r;}
export function factor(r){if(r.kind==='exception')return r.manual;if(r.kind==='period')return r.group==='COF'?1:.7;if(r.kind==='overdue')return 1.1;if(r.group==='COF'||r.kind==='cof')return 1.5;return 1.3+(Number(r.kind.slice(1))-3)*.02;}
export function ntuRow(r){const active=r.pos>0&&r.mindue>0&&r.amount>=r.mindue,liquidated=r.pos>0&&r.amount>=r.pos,hs=r.override!==null?r.override:liquidated?.2:r.manual;return {active,liquidated,hs,lit:active?r.pos:0,responsibility:active?r.amount*hs:0};}
export function calculate(d){const s=d.settings,cof=d.cash.filter(r=>r.group==='COF').reduce((a,r)=>a+r.amount,0),non=d.cash.filter(r=>r.group==='NON').reduce((a,r)=>a+r.amount,0),pos=d.cash.reduce((a,r)=>a+r.amount*factor(r),0),kcof=s.cof>0?cof/s.cof:0,knon=s.non>0?non/s.non:0,cashKpi=kcof*s.wcof+knon*s.wnon,ntuKpi=s.ntu>0?s.done/s.ntu:0,total=cashKpi*rate(s.bands.cash,ntuKpi)+ntuKpi*rate(s.bands.ntu,cashKpi),bonusRate=rate(s.bands.bonus,total),bonus=pos*bonusRate,ntuPos=d.ntu.reduce((a,r)=>a+r.pos,0),lit=d.ntu.reduce((a,r)=>a+ntuRow(r).lit,0),ratio=ntuPos>0?lit/ntuPos:0,responsibility=d.ntu.reduce((a,r)=>a+ntuRow(r).responsibility,0),paidBonus=bonus*(ratio+1e-12>=.68?1:.8),paidResponsibility=ratio+1e-12>=.85?responsibility:0,gross=s.salary+paidBonus+paidResponsibility,taxable=Math.max(0,gross-s.deduct-s.dependents*s.perDependent-s.insurance);let tax=0;for(let i=0;i<s.taxBands.length;i++){const [start,r]=s.taxBands[i],end=s.taxBands[i+1]?.[0]??Infinity;tax+=Math.max(0,Math.min(taxable,end)-start)*r;}tax=Math.round(tax);return {cof,non,pos,kcof,knon,cashKpi,ntuKpi,total,bonusRate,bonus,ntuPos,lit,ratio,responsibility,paidBonus,paidResponsibility,gross,tax,net:gross-tax,actual:cof+non+d.ntu.reduce((a,r)=>a+r.amount,0)};}
